def main():
    print("Fazendo login como admin...")
    token = login_admin()
    print("Login OK\n")

    # 1. Criar empresas (idempotente — reaproveita as que já existem)
    print("Criando empresas...")
    empresa_map = {}
    existing = requests.get(f"{API}/empresas/").json()
    for e in existing:
        empresa_map[e["nome"]] = e["id"]
    if empresa_map:
        print(f"  {len(empresa_map)} empresas já existentes carregadas")

    cnpj_base = 10000000000000
    for i, nome in enumerate(CLIENTES):
        if nome in empresa_map:
            continue
        cnpj = f"{cnpj_base + i:014d}"
        cnpj_fmt = f"{cnpj[:2]}.{cnpj[2:5]}.{cnpj[5:8]}/{cnpj[8:12]}-{cnpj[12:]}"
        r = requests.post(f"{API}/empresas/", json={
            "nome": nome, "cnpj": cnpj_fmt, "setor": "Indústria",
            "cidade": "São Paulo", "estado": "SP"
        }, headers=h(token))
        if r.status_code in (200, 201):
            empresa_map[nome] = r.json()["id"]
            print(f"  OK {nome} (id={empresa_map[nome]})")
        else:
            print(f"  ERRO {nome}: {r.status_code}")

    # 2. Criar recrutadores
    print("\nCriando recrutadores...")
    for nome, email in RECRUTADORES:
        r = requests.post(f"{API}/auth/registro", json={
            "nome": nome, "email": email, "senha": "Senha123!",
            "perfil": "recrutador"
        })
        if r.status_code in (200, 201):
            print(f"  OK {nome}")
        else:
            print(f"  AVISO {nome}: {r.status_code} (pode já existir)")

    # 3. Criar vagas
    print("\nCriando vagas...")
    total = 0
    for v in VAGAS_EXCEL:
        eid = empresa_map.get(v["cliente"])
        if not eid:
            print(f"  SKIP {v['titulo']} - empresa nao encontrada: {v['cliente']}")
            continue
        payload = {
            "titulo": v["titulo"],
            "empresa_id": eid,
            "modalidade": v["modalidade"],
            "tipo_contrato": "temporario",
            "quantidade_vagas": v["quantidade_vagas"],
            "data_abertura": v["data_abertura"],
            "prioridade": v["prioridade"],
            "recrutador_responsavel": v["recrutador_responsavel"],
            "status": v["status"],
            "vaga_pcd": v["vaga_pcd"],
            "descricao": v["descricao"],
            "local": "São Paulo, SP",
            "encaminhados": 0,
            "publico_alvo": "ambos",
        }
        r = requests.post(f"{API}/vagas/", json=payload, headers=h(token))
        if r.status_code in (200, 201):
            total += 1
        else:
            print(f"  ERRO {v['titulo']}: {r.status_code} {r.text[:100]}")

    print(f"\n{total} vagas criadas")
    print(f"Empresas: {len(empresa_map)}")
    print("Seed concluido!")

if __name__ == "__main__":
    main()
